    "id": "beca_de_integración_territorial_bit_52728",
    "titulo": "Beca de Integración Territorial (BIT)",
    "url": "https://www.chileatiende.gob.cl/fichas/52728-beca-de-integracion-territorial-bit",
    "categoria": "becas-y-creditos",
